def page(path, title, description, body, *, noindex=False, tour=False):
    canonical = '/' if path == 'index.html' else '/' + path.removesuffix('index.html')
    if not noindex: PAGES.append(canonical)
    schema = [{"@context":"https://schema.org","@type":"WebPage","name":title,"description":description,"url":URL+canonical,"isPartOf":{"@type":"WebSite","name":"RentSketch","url":URL+"/"}}]
    if canonical == '/':
        schema += [{"@context":"https://schema.org","@type":"Organization","name":"Rent Sketch L.L.C.","alternateName":"RentSketch","url":URL+"/","logo":URL+"/assets/brand-mark.svg"},{"@context":"https://schema.org","@type":"SoftwareApplication","name":"RentSketch","applicationCategory":"BusinessApplication","operatingSystem":"Web browser","url":URL+"/","description":description,"image":URL+"/assets/event-reception-3d.webp","featureList":["2D event floor plans","3D event previews","Supported rental equipment catalog","Saving, printing and sharing one event","Business branding and website embeds"],"offers":[{"@type":"Offer","name":"One-time Event Pass","price":"9.99","priceCurrency":"USD","url":URL+"/event-pass/","description":"One event with 30 days of editing, saving, printing and sharing. No subscription."},{"@type":"Offer","name":"Starter business subscription","price":"49.00","priceCurrency":"USD","url":URL+"/business/pricing.html","description":"Starter business plan, billed monthly. A 14-day trial is available without a credit card."}]}]
    if canonical == '/event-pass/':
        schema.append({"@context":"https://schema.org","@type":"SoftwareApplication","name":"RentSketch Event Pass","applicationCategory":"DesignApplication","operatingSystem":"Web browser","url":URL+"/event-pass/","description":description,"offers":{"@type":"Offer","name":"One-time Event Pass","price":"9.99","priceCurrency":"USD","url":event_pass_url('schema_event_pass'),"description":"One event for 30 days. No subscription or automatic renewal."}})
    if canonical in {'/party-rental-software/','/event-rental-software/','/tent-rental-software/'}:
        schema.append({"@context":"https://schema.org","@type":"SoftwareApplication","name":"RentSketch","applicationCategory":"BusinessApplication","operatingSystem":"Web browser","url":URL+canonical,"description":description,"featureList":["Branded 2D and 3D event designer","Rental product catalog with names, dimensions and prices","Customer event layouts","Quote requests","Website embed and direct designer links","Business dashboard"],"offers":{"@type":"Offer","name":"Starter business subscription","price":"49.00","priceCurrency":"USD","url":URL+"/business/pricing.html","description":"Starter business plan, billed monthly. A 14-day trial is available without a credit card."}})
    if canonical != '/':
        schema.append({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"RentSketch","item":URL+"/"},{"@type":"ListItem","position":2,"name":title.split(' | ')[0],"item":URL+canonical}]})
    imports = '<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"}}</script>' if tour else ''
    save(path, f'''<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)}</title><meta name="description" content="{escape(description, quote=True)}">
<link rel="canonical" href="{URL+canonical}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}">
<meta name="theme-color" content="#183429"><link rel="icon" type="image/svg+xml" href="/assets/brand-mark.svg">
<meta property="og:type" content="website"><meta property="og:site_name" content="RentSketch"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{URL+canonical}">
<meta property="og:image" content="{URL}/assets/rentsketch-social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="RentSketch event layout software: 2D plans and 3D previews">
<meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/marketing.css?v={VERSION}">
<script type="application/ld+json">{json.dumps(schema)}</script>{imports}
<script src="/marketing.js?v={VERSION}" defer></script></head><body>
{NAV}<main id="main">{body}</main>{FOOT}
{'<script type="module" src="/marketing-tour.js?v='+VERSION+'"></script>' if tour else ''}
</body></html>''')

