page('demo/index.html','RentSketch Quick Demo | 2D & 3D Event Planner','Watch a quick RentSketch example in 2D and 3D. See how a furnished event layout comes together before opening your own designer.', f'''<section class="page-hero"><div class="wrap"><div class="eyebrow">Free Quick Demo</div><h1>See how RentSketch<br>works in a real layout.</h1><p>Take a quick look at a furnished 40 × 60 pole tent. Switch between the 2D plan and 3D scene and see what the planner can do. Nothing is saved or submitted.</p></div></section><section class="section"><div class="wrap">'''+studio(True)+f'''<p class="demo-caption">Interactive example using RentSketch’s 3D renderer. This demonstration does not save designs or make bookings.<br>Layouts are planning aids; review the actual site and installation requirements with your rental team.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="{event_pass_url('rentsketch_demo')}">Start my own event · $9.99 ↗</a><a class="btn" href="/business/">For rental companies</a></div><p class="micro" style="text-align:center">One event · 30 days · no subscription.</p></div></section>''',tour=True)

page('business/index.html','Event Design Software for Rental Companies | RentSketch','Give rental customers a branded 2D and 3D designer on your website. Configure your catalog, review customer plans and manage quote requests in RentSketch.', '''<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">RentSketch for rental companies</div><h1>Your inventory.<br><span>Their event.<br>One clear picture.</span></h1><p class="lead">Help customers visualize the setup before your next quote. Bring your catalog, branding and customer layouts into a single planning workflow.</p><div class="actions"><a class="btn primary" href="/business/signup.html">Start a 14-day free trial ↗</a><a class="btn" href="/demo/">Explore the demo</a></div><p class="micro">No credit card. No automatic charge when the trial ends.</p></div>'''+studio()+'''</div></section><section class="section"><div class="wrap two-col"><div><div class="eyebrow">Built around your rental catalog</div><h2>Give every quote<br>a visual starting point.</h2><p>A request for “a tent for 80 people” leaves a lot to discuss. A layout helps you review tables, chairs, dancing and service areas together.</p><p>RentSketch organizes that conversation around the products and pricing you configure. Supported visual models give the design recognizable equipment rather than a blank diagram.</p></div><ul class="benefits"><li><strong>Products:</strong> add names, prices, dimensions and supported visuals.</li><li><strong>Branding:</strong> configure your name, logo and customer experience.</li><li><strong>Requests:</strong> review submitted customer designs and follow up.</li><li><strong>Installation:</strong> embed the designer on an approved website domain.</li><li><strong>Billing:</strong> manage your subscription in the business dashboard.</li></ul><p class="support-line">Explore by workflow: <a href="/party-rental-software/">party rental software</a> · <a href="/event-rental-software/">event rental software</a> · <a href="/tent-rental-software/">tent rental software</a></p></div></section><section class="section tinted"><div class="wrap"><div class="section-heading"><div class="eyebrow">Your first workspace</div><h2>Know what comes next.</h2></div><div class="steps"><article class="step"><span class="number">01</span><h3>Build your catalog.</h3><p>Add the products you rent. Set prices, sizes and visuals in Products. Review the details before customers use the designer.</p></article><article class="step"><span class="number">02</span><h3>Make it yours.</h3><p>Configure Branding, open your customer designer and check an example layout. Confirm the catalog represents your business.</p></article><article class="step"><span class="number">03</span><h3>Install and share.</h3><p>Add your domain in Install and place the embed on your website. Customer quote requests arrive in Requests.</p></article></div><p class="support-line"><a href="/help/#business">Read the setup walkthrough →</a></p></div></section><section class="section"><div class="wrap faq-layout"><div><div class="eyebrow">An honest fit</div><h2>Visual planning for your existing operation.</h2><p>Keep your booking process. Add a clearer way to plan.</p></div>'''+faq([('Will it work with my equipment?','The catalog supports dimensions, pricing and mappings to the visual library. Check your required equipment during the free trial; a custom 3D model for every product is not automatically included.'),('Will it automatically sync my rental system?','There is no automatic connection to every rental system. Embedding works independently; supported integrations and webhook workflows require configuration.'),('Can I collect rental deposits?','Deposit workflows require the appropriate business configuration and Stripe onboarding. A RentSketch software subscription is separate from your customers’ equipment payments.'),('How much is a business subscription?','Current plans are Starter $49/month, Pro $99/month and Business $199/month. Annual options are $490, $990 and $1,990. <a href="/business/pricing.html">Compare plans</a>.')])+'''</div></section>'''+cta(),tour=True)

page('business/pricing.html','RentSketch Pricing | Business Plans & One-Time Event Pass','Compare RentSketch business plans from $49/month with a 14-day free trial, or a $9.99 Event Pass for one event. See annual pricing and renewal details.', f'''<section class="page-hero"><div class="wrap"><div class="eyebrow">Clear plans. Two ways to get started.</div><h1>A business workspace.<br>Or just your next event.</h1><p>Planning one event? Pay $9.99 once. Running a rental company? Start a 14-day business trial.</p><div class="actions"><a class="btn primary" href="{event_pass_url('rentsketch_pricing_hero')}">Start my event · $9.99 ↗</a><a class="btn" href="/business/signup.html">Start business trial</a></div></div></section><section class="section" id="business-plans"><div class="wrap"><div class="event-pass" id="event-pass"><div><span class="pill">For individual event planners</span><h3 style="margin-top:13px">Event Pass · $9.99 once</h3><p>One event. 30 days to edit, save, print and share. Renew the same event for $4.99 for 30 more days only when you choose. No recurring subscription. Equipment rentals are separate.</p></div><div class="actions"><a class="btn primary" href="{event_pass_url('rentsketch_pricing_event_pass')}">Start planning · $9.99 ↗</a><a class="btn" href="/demo/">Watch free demo</a></div></div><div class="section-heading center" style="margin-top:56px"><div class="eyebrow">Business plans</div><h2>For rental companies.</h2></div>'''+prices()+'''</div></section><section class="section tinted"><div class="wrap faq-layout"><div><h2>Before you choose.</h2><p>Questions about the right fit?<br><a href="mailto:hello@rentsketch.com">Contact RentSketch</a>.</p></div>'''+faq([('Will the business trial charge me automatically?','No. You do not enter a card to start. After 14 days, choose and purchase a subscription in your dashboard to continue.'),('When does a paid business plan start?','The subscription begins when you complete Stripe Checkout. The billing interval and total are shown before you pay. Monthly or annual subscriptions renew until canceled.'),('Can I cancel a business subscription?','Use Billing → Manage Billing in Stripe in your dashboard to manage payment details, invoices and cancellation. Check the effective date displayed by Stripe.'),('Does the Event Pass include rental equipment?','No. The Event Pass pays for software access to one design. Equipment, delivery, installation and the rental order are separate.'),('I already have a confirmed Friendly Party Rental booking. Do I pay again?','An eligible active confirmed Friendly booking includes design access. Use the <a href="/my-event/?tenant=friendly&amp;mode=order">existing order login</a> with your first name and order number.'),('How do I get back to an event I paid for?','Payment returns you to the saved event. Your access email contains a private link, and <a href="/my-event/">Open my saved event</a> can send it again. Keep the private link safe.')])+'''</div></section>''')

page('business/signup.html','Start Your 14-Day Business Trial | RentSketch','Create a RentSketch rental business workspace. Try the branded event designer and dashboard for 14 days. No credit card or automatic charge.', '''<div class="wrap signup-layout"><div><div class="eyebrow">Your RentSketch business workspace</div><h1>Let’s put your rentals<br>in the picture.</h1><p>Start your 14-day trial. Set up your catalog, explore customer layouts and see how RentSketch fits your business.</p><ul class="benefits"><li>No credit card required</li><li>No automatic charge when the trial ends</li><li>Choose a paid subscription in Billing when you’re ready</li></ul><p class="support-line">Already have an account? <a href="/dashboard/">Log in →</a></p><p class="support-line">Planning one event? <a href="/event-pass/">Get the $9.99 Event Pass →</a></p></div><div class="signup-box"><form id="business-signup"><h2>Create your workspace</h2><div class="field"><label for="businessName">Business name</label><input id="businessName" name="businessName" autocomplete="organization" required maxlength="120"></div><div class="field"><label for="contactEmail">Work email</label><input id="contactEmail" name="contactEmail" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="new-password" required minlength="8" maxlength="72" aria-describedby="password-hint"><span id="password-hint" class="micro">8–72 characters. Use a unique password.</span></div><fieldset class="plan-choices"><legend>Choose a plan to try</legend><label class="plan-choice"><input type="radio" name="plan" value="starter"><strong>Starter</strong><span>$49/month after trial</span></label><label class="plan-choice"><input type="radio" name="plan" value="pro" checked><strong>Pro</strong><span>$99/month after trial</span></label><label class="plan-choice"><input type="radio" name="plan" value="commerce"><strong>Business</strong><span>$199/month after trial</span></label></fieldset><p class="micro">Selecting a plan starts a free trial. It does not start a paid subscription.</p><div class="form-error" id="signup-error" role="alert" hidden></div><button class="btn primary" type="submit">Create my free workspace ↗</button><p class="micro" style="margin:15px 0 0">Your account and event data are handled as described in our <a href="/privacy/">privacy notice</a>.</p></form><div class="success-box" id="signup-success" hidden role="status"><h2>Your workspace is ready.</h2><p>No charge was made. Start by adding products, setting your branding and previewing your customer designer.</p><a class="btn primary" href="/dashboard/#/overview">Open my dashboard ↗</a></div></div></div><script src="/business/signup.js?v='''+VERSION+'''" defer></script>''',noindex=True)

articles = [
('tent-layout-software','Tent Layout Software for 2D & 3D Event Planning','Plan a tent layout with real dimensions, tables, chairs and a dance floor. Explore the same event in 2D and 3D with RentSketch.','Plan the tent.<br>Understand the space.', 'Turn a tent size into a layout you can discuss with your customer, venue and rental team.',[
('Start with the footprint, not just the guest count.','A guest count is a starting point. The arrangement of tables, service areas and a dance floor changes how the event uses a tent. Begin with the tent’s dimensions and style, then identify what has to fit inside. A pole tent also introduces interior poles that need to remain visible in the planning conversation.'),
('Build the event around the equipment.','Add the table types and chair arrangements you intend to use. Include the DJ, buffet, bar and other equipment before calling the plan complete. Reserve circulation space and review entrances instead of filling every available area with seating. RentSketch’s visual plan helps show those tradeoffs before setup day.'),
('Use 2D for arrangement and 3D for perspective.','The overhead view makes it easier to compare positions. The 3D view gives customers a different way to understand the same design. Review both when discussing what the event will look like. You can explore a furnished example without signing up on the product demo page.'),
('Review the real site before confirming the rental.','A diagram is a planning aid. Actual ground conditions, tent anchoring, exits and installation clearances must be checked with the rental team and venue. Manufacturer instructions and local requirements determine the installation; an attractive digital plan does not approve it.'),
('Bring the plan into the quote.','Rental businesses can configure products and prices, map supported visuals and review customer quote requests. Confirm availability and final service details in your rental workflow. Individual planners can purchase a separate Event Pass when they need to edit, save and share their own event.')]),
('tent-diagram-software','Tent Diagram Software | Clear Event & Seating Plans','Create visual tent diagrams with tables, chairs and event equipment. Review overhead layouts and 3D views before discussing the final setup with your rental team.','Make the tent diagram<br>easy to understand.','Create a shared reference for the equipment, the arrangement and the questions still to resolve.',[
('What a useful tent diagram includes.','Start with the tent’s size and style. Add each table, the intended seating and the equipment that occupies floor space. A dance floor, beverage station or service table belongs in the first draft, because adding it later can change the entire seating arrangement.'),
('Show the space between the objects.','The blank parts of a diagram matter. People need routes from the entrance to their seats and to service areas. Keep central poles and other obstructions visible. Share the drawing with the rental team so they can review clearances and the actual installation conditions.'),
('Compare the overhead plan with a 3D view.','An overhead diagram is useful for placement, but many customers find a perspective view easier to understand. RentSketch lets you see the same event in both. The product demo shows how the relationship between tables, seating and the tent changes from another viewpoint.'),
('Use the diagram in a customer conversation.','For rental companies, a diagram is a starting point for a quote discussion. Configure supported equipment in your catalog and bring customer plans into your dashboard. Review the design alongside availability, site access and delivery details before accepting a rental order.'),
('Keep a version everyone can refer to.','An individual Event Pass provides 30 days of editing, saving, printing and sharing one design. Use a saved plan for discussion, and communicate changes when the event details move. Software access does not include rental equipment or approval of a tent installation.')]),
('party-rental-software','Party Rental Software & Party Rental Business Software | RentSketch','Party rental software for rental businesses that need visual customer layouts, branded catalogs and quote requests beside booking, inventory and delivery operations.','Party rental software<br>built for the way rental businesses sell events.','Give party-rental customers a visual way to plan tents, tables, chairs and event space before your team confirms the booking.',[
('Party rental business software for the customer-planning step.','RentSketch gives party and event rental businesses a branded 2D and 3D event designer, a configurable rental-product catalog, saved customer layouts and quote requests. It is built for the visual planning step that often happens before a rental team finalizes availability, delivery and installation details.'),
('Party rental inventory software starts with an accurate product catalog.','Add rental product names, categories, dimensions, prices, photos and supported visual mappings so customers plan with recognizable equipment. RentSketch does not replace live stock-count or reservation software, so confirm actual inventory, date availability and holds in your booking system before accepting an order.'),
('Party rental management software should fit the operation you already run.','Use RentSketch beside your existing booking, delivery and accounting workflow. The business dashboard keeps products, customer designs and quote requests together, while your rental system remains authoritative for reservations, contracts, route scheduling and final payments unless you configure a supported integration.'),
('Party and event rental software needs a customer-facing experience.','Install the branded designer on an approved website domain or share a direct designer link. Customers can work through the visual questions before they call: tent footprint, seating, dance floor and other equipment. That gives your staff a clearer starting point for the quote conversation.'),
('Software for party rental companies should make the customer request easier to understand.','If you searched for software for party rental, compare the jobs each system actually owns. RentSketch handles the visual customer-planning layer: branded equipment catalogs, 2D and 3D layouts, saved designs and quote requests. Keep reservations, availability, contracts, routing and accounting in the operational tools that run those workflows.'),
('Try the workflow before you subscribe.','Start the 14-day business trial with no credit card. Add several real products, build a representative customer event and review the resulting request in your dashboard. Then decide whether the visual-planning workflow earns a place beside the rental tools you already use.')]),
('tent-rental-software','Tent Rental Software | Layouts, Quotes & Visual Planning | RentSketch','Tent rental software for visual layouts, tent catalogs and quote requests. Help customers picture pole and frame tent setups before availability and installation are confirmed.','Tent rental software<br>for layouts, catalogs and clearer quote conversations.','Give tent-rental customers a visual starting point before your team confirms inventory, anchoring, delivery and installation.',[
('Show customers the tent before the quote becomes a spreadsheet.','A tent rental often begins with a guest count and a size question. RentSketch lets customers start with a supported tent model, add tables, chairs and a dance floor, and review the same event in 2D and 3D before your team finalizes the rental.'),
('Build a tent catalog with real dimensions and prices.','Rental businesses can configure product names, categories, dimensions, prices, photos and supported visual mappings. Pole and frame tent visuals can give customers a clearer picture of the footprint and interior planning conversation.'),
('Use RentSketch beside tent inventory and scheduling software.','RentSketch does not currently replace component-level tent inventory, crew scheduling, route planning or maintenance systems. Keep your operational tent-rental software authoritative for poles, stakes, sidewalls, availability and installation logistics.'),
('Bring customer layouts into the quote workflow.','A submitted plan can give your staff useful context before calling the customer: the selected tent, seating idea, dance-floor placement and other supported rentals. Treat the plan as a request, then verify the site, inventory and installation requirements before booking.'),
('Try it with one of your common tent packages.','Use the 14-day business trial without a credit card. Add one or two common tents and supporting rentals, preview the branded customer experience and review a test request before deciding whether to subscribe.')]),
('event-rental-software','Party and Event Rental Software | RentSketch','Party and event rental software for visual customer layouts, branded rental catalogs and quote requests. Use RentSketch beside reservation, inventory and delivery systems.','Party and event rental software<br>for customer layouts and visual quote requests.','Turn a customer’s guest count and equipment list into a 2D and 3D event plan your rental team can review.',[
('Event rental software should give customers a common reference.','A list of rentals rarely explains the whole event. RentSketch lets customers arrange tents, seating, dance floors and supported equipment in one visual plan so the rental team can discuss the same picture.'),
('Build a catalog around the equipment you actually rent.','Configure names, categories, prices, dimensions, photos and supported visual mappings. The designer uses that catalog for customer planning and the business dashboard keeps submitted layouts and quote requests attached to the rental-company workspace.'),
('Use it with your existing event rental management software.','RentSketch focuses on visual planning and quote requests. It does not currently replace full reservation inventory, dispatch, route scheduling, accounting or contract systems. Keep those operational systems authoritative and use RentSketch to improve the layout and quote conversation.'),
('Searching for “rent event registration software”?','If you mean attendee registration, ticketing or check-in, RentSketch is not that category of software. RentSketch is for rental-product and physical event-layout planning. If your business needs guest registration, keep that in your registration platform and use RentSketch for the physical event setup.'),
('Start with a real customer scenario.','Use the 14-day no-card trial to model several products, open the customer designer and submit a test quote request. Review whether the layout gives your staff better information before you choose a paid business plan.')]),
('event-layout-software','Event Floor Plan Software | 2D & 3D Layouts | RentSketch','Create event floor plans with tents, seating and rental equipment. Explore 2D and 3D layouts for weddings, parties and rental quote conversations.','An event floor plan<br>people can picture.','Start with the space. Add the equipment. See how the event comes together.',[
('Define the event before arranging the tables.','List the guest count and the activities you need to accommodate. A seated meal, dancing, a buffet and a presentation use space in different ways. Identify those areas first so the drawing represents the whole event rather than only the dining tables.'),
('Build from a measured footprint.','Choose the tent or planning area and verify its dimensions. Add furniture with the sizes you intend to rent. Keep permanent obstacles and routes in the discussion. A plan is most useful when the equipment and space match the actual event conditions.'),
('Use two views for different questions.','In 2D, compare placement and look at the arrangement from above. In 3D, explore perspective and help others understand the setup. RentSketch uses the same event for both views, so you do not need to redraw the design to explain another viewpoint.'),
('Choose access for the job.','Individual event planners can watch the free Quick Demo, then purchase a $9.99 Event Pass for 30 days of access to one design. Rental companies use a separate business workspace with a catalog, branding and customer quote workflow.'),
('Review the plan with the people setting up.','Use the plan to ask specific questions about the equipment, entrances, service areas and installation. Confirm availability and site suitability with the venue and rental team. The software is a visual planning tool, not an engineering approval or equipment reservation.')]),
('wedding-layout-planner','Wedding Reception Layout Planner | 2D & 3D | RentSketch','Plan a wedding reception layout with tables, chairs, a tent and a dance floor. Preview the arrangement in 2D and 3D and share a clearer event plan.','Picture the reception.<br>Plan the details.','Bring tables, dancing and gathering spaces into one wedding layout.',[
('Start with the moments you are planning for.','Think about dinner, speeches, dancing and how guests arrive. Decide whether the ceremony shares the same space or uses a separate area. Those decisions determine what the reception layout needs to accommodate before you choose individual table positions.'),
('Place the large areas first.','Begin with the tent or reception footprint. Add the dance floor, head table and service areas, then work through the guest tables. Make room for the equipment that is easy to overlook, such as a DJ area or a buffet table.'),
('Review table shapes and the guest count together.','Round and banquet tables produce different arrangements. Choose the tables and chair counts that match the intended rental, and leave the space between them visible. The venue and rental team should review the plan against the real site and event requirements.'),
('Share the picture, not only a list.','RentSketch lets you compare an overhead layout with a 3D view of the same event. Use the picture to discuss changes with the people helping you plan. The sample reception on our demo page gives you a way to explore the views before buying access.'),
('Choose a one-time Event Pass for your wedding.','A $9.99 Event Pass covers one design for 30 days of editing, saving, printing and sharing. The Quick Demo is free, watch-only and replayable. If you need longer, an optional $4.99 renewal adds 30 days to the same event. This is software access; your rental equipment and venue are booked separately.')])
]
consumer_articles={'tent-layout-software','tent-diagram-software','event-layout-software','wedding-layout-planner'}
for slug,title,desc,heading,intro,sections in articles:
    if slug in consumer_articles:
        buy=event_pass_url('rentsketch_'+slug.replace('-','_'))
        body='<section class="page-hero"><div class="wrap"><div class="eyebrow">Plan one event in 2D + 3D</div><h1>'+heading+'</h1><p>'+intro+'</p><div class="actions"><a class="btn primary" href="'+buy+'">Start my event · $9.99 ↗</a><a class="btn" href="/demo/">Watch free demo</a></div><p class="micro">One event · 30 days · no subscription · rental equipment is separate.</p></div></section><section class="section"><div class="wrap guide"><article>'
        body+=''.join('<h2>'+h+'</h2><p>'+p+'</p>' for h,p in sections)
        body+='</article><aside class="guide-aside"><h3>Ready to make it your event?</h3><p>Get 30 days to edit, save, print and share one event layout.</p><a class="btn primary" href="'+buy+'">Start planning · $9.99 ↗</a><a href="/demo/">Watch the free demo →</a><a href="/event-pass/">Event Pass details →</a><a href="/business/">For rental businesses →</a></aside></div></section>'+event_cta('rentsketch_'+slug.replace('-','_')+'_footer')
    else:
        body='<section class="page-hero"><div class="wrap"><div class="eyebrow">RentSketch planning resources</div><h1>'+heading+'</h1><p>'+intro+'</p><div class="actions"><a class="btn primary" href="/business/signup.html">Start business trial ↗</a><a class="btn" href="/demo/">Explore a layout</a></div></div></section><section class="section"><div class="wrap guide"><article>'
        body+=''.join('<h2>'+h+'</h2><p>'+p+'</p>' for h,p in sections)
        body+='</article><aside class="guide-aside"><h3>See it in a real layout.</h3><p>Explore an example with tables, chairs and a dance floor. Switch between the plan and the 3D view.</p><a class="btn primary" href="/demo/">Open the demo ↗</a><a href="/business/">For rental businesses →</a><a href="/party-rental-management-software/">Management software →</a><a href="/party-rental-inventory-software/">Inventory software →</a><a href="/tent-rental-software/">Tent rental software →</a></aside></div></section>'+software_intent_links()+cta()
    page(slug+'/index.html',title,desc,body)

page('event-pass/index.html','3D Event Planner | $9.99 One-Time Event Pass | RentSketch','Plan one event in 2D and 3D for $9.99 once. Get 30 days to edit, save, print and share your layout. No subscription or automatic renewal.', f'''<section class="hero"><div class="wrap hero-grid"><div><div class="eyebrow">For weddings, parties and tent events</div><h1>Plan one event.<br><span>See it before setup day.</span></h1><p class="lead">Arrange tents, tables, chairs, dance floors and more in 2D and 3D. Your Event Pass gives you 30 days to edit, save, print and share one event.</p><div class="actions"><a class="btn primary" href="{event_pass_url('rentsketch_event_pass_page_hero')}">Start my event · $9.99 ↗</a><a class="btn" href="/demo/">Watch the free demo</a></div><div class="inline-proof"><span>$9.99 once</span><span>30 days</span><span>No subscription</span></div><p class="micro">Stripe hosts payment. Rental equipment, delivery and venue costs are separate.</p></div>'''+studio()+f'''</div></section><section class="section"><div class="wrap"><div class="section-heading center"><div class="eyebrow">What the Event Pass includes</div><h2>One layout you can keep working on.</h2></div><div class="steps"><article class="step"><span class="number">01</span><h3>Build the layout.</h3><p>Start with the space or tent. Add tables, chairs, a dance floor and other supported event equipment.</p></article><article class="step"><span class="number">02</span><h3>Switch between 2D + 3D.</h3><p>Use the floor plan for placement and the 3D view to help picture the same event.</p></article><article class="step"><span class="number">03</span><h3>Save, print and share.</h3><p>Return through your private access link during the 30-day term and keep refining the same event.</p></article></div></div></section><section class="section tinted"><div class="wrap two-col"><div><div class="eyebrow">Simple pricing</div><h2>$9.99 once.<br>No recurring plan.</h2><p>The Event Pass is software access for one event for 30 days. If you need more time, you can optionally renew the same event for $4.99 for another 30 days.</p><p>No subscription. No automatic renewal. Completing a layout does not reserve rental equipment.</p></div><div class="event-pass"><div><span class="pill">One Event Pass</span><h3 style="margin-top:13px">$9.99 · 30 days</h3><p>Edit · save · print · share · 2D + 3D</p></div><a class="btn primary" href="{event_pass_url('rentsketch_event_pass_page_pricing')}">Start planning · $9.99 ↗</a></div></div></section><section class="section"><div class="wrap faq-layout"><div><h2>Before you pay.</h2><p>Know exactly what the pass does.</p></div>'''+faq([('Does $9.99 include rental equipment?','No. The Event Pass pays only for RentSketch software access. Tents, tables, chairs, delivery, installation and venue costs are separate.'),('Is this a subscription?','No. The $9.99 Event Pass is a one-time payment for 30 days of access to one event. It does not renew automatically.'),('Can I see it before paying?','Yes. Use the free demo to see how 2D and 3D layouts work. The Event Pass is for creating and keeping your own event.'),('What happens after I pay?','Stripe verifies the payment, RentSketch opens your saved event, and an access email is sent with a private link so you can return during the access period.'),('Can I use it for a wedding?','Yes. It is intended for a single event such as a wedding reception, party, tent event or similar layout-planning project.')])+'''</div></section>'''+event_cta('rentsketch_event_pass_page_footer'),tour=True)

page('help/index.html','Getting Started & Purchase Help | RentSketch','Set up your rental business workspace, understand the trial, manage subscriptions and recover a purchased Event Pass. RentSketch customer help.', '''<section class="page-hero"><div class="wrap"><div class="eyebrow">RentSketch help</div><h1>Your next step,<br>made clear.</h1><p>Set up your workspace or get back to the event you purchased.</p></div></section><section class="section"><div class="wrap guide"><article><h2 id="business">Set up a business workspace</h2><ol><li><a href="/business/signup.html">Create a 14-day trial</a>. No credit card is required.</li><li>Open <strong>Products</strong> and add the equipment you want customers to use. Set names, dimensions, prices and supported visual models.</li><li>Open <strong>Branding</strong> and configure your business identity.</li><li>Open <strong>Install</strong>, preview your designer, and add your website’s domain before embedding.</li><li>Review your own customer journey before publishing. Submitted quote requests appear in <strong>Requests</strong>.</li></ol><h2>Choose a paid business subscription</h2><p>In your dashboard, open Billing, choose a plan and select monthly or yearly billing. Stripe Checkout displays the payment details before you subscribe. Your trial does not charge you automatically.</p><p>If you already have a subscription, use Manage Billing in Stripe to manage it. Returning from Checkout alone does not confirm payment; the dashboard reads the saved subscription status.</p><h2>Purchase an individual Event Pass</h2><p>Watch the free Quick Demo to see how the 2D and 3D planner works. The demo is watch-only and does not create or save your event. When you are ready to make your own layout, review the $9.99 price for 30 days of access, provide your email and continue to Stripe.</p><p>After verified payment, you return to the event and receive a private access link by email. Keep the link private. Equipment rentals are a separate purchase.</p><h2>Find an event you already paid for</h2><p>Use your purchase email’s private link, or visit <a href="/my-event/">Open my saved event</a> and request the access email again. Check the spelling of the email address and your spam folder. A pending payment or a canceled checkout does not activate a pass.</p><h2>Get help with a purchase</h2><p>Email <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with the account email, approximate purchase date and what went wrong. Do not send passwords or full card details.</p></article><aside class="guide-aside"><h3>Quick links</h3><a href="/dashboard/">Business dashboard →</a><a href="/my-event/">Open my saved event →</a><a href="/business/pricing.html">Pricing →</a><a href="/demo/">Explore the demo →</a></aside></div></section>''')

page('privacy/index.html','Privacy Notice | RentSketch','Learn how RentSketch uses account information, event designs and payment references to operate its event planning software.', '''<section class="page-hero"><div class="wrap"><h1>Privacy at RentSketch.</h1><p>Information used to provide the event design service.</p></div></section><section class="section"><div class="wrap guide"><article><h2>Account and event information</h2><p>RentSketch stores business account information, including the business name, email address and a hashed password. The service also stores event designs and the information submitted with quote requests so users and the relevant rental business can work with those plans.</p><h2>Payments and access</h2><p>Stripe hosts checkout and handles payment information. RentSketch stores payment references, payment status, the purchase email and access periods to provide subscriptions or Event Pass access. Private event links are used to reopen a purchased design.</p><h2>Browser storage</h2><p>The designer uses browser storage for draft and session information. The business dashboard stores a sign-in token so the account can remain signed in. Signing out clears the dashboard token; clearing browser storage can remove local drafts and preview state.</p><h2>Service providers and rental businesses</h2><p>Hosting, payment and email services process information needed to operate RentSketch. When you use a rental company’s designer and submit an event or quote request, that business receives the relevant information. Its handling of rental orders is separate from RentSketch software access.</p><h2>Questions and requests</h2><p>Contact <a href="mailto:hello@rentsketch.com">hello@rentsketch.com</a> with privacy, account or data requests. Include enough information to identify your account, but never send a password, full payment card number or private event access link.</p></article></div></section>''')

page('404.html','Page Not Found | RentSketch','Find your way back to RentSketch event design software.', '''<div class="error-panel"><div class="eyebrow">404 · Page not found</div><h1>Let’s get you back<br>to the plan.</h1><p>This address does not match a RentSketch page.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="/">Go to RentSketch</a><a class="btn" href="/my-event/">Open my saved event</a></div></div>''',noindex=True)

# Static SVG uses the same dimensions and furniture positions as the 3D example.
svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 480"><defs><pattern id="grid" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M12 0H0V12" fill="none" stroke="#dce5d7" stroke-width=".6"/></pattern><pattern id="wood" width="24" height="24" patternUnits="userSpaceOnUse"><rect width="24" height="24" fill="#d8b78b"/><path d="M0 12H24M12 0V24" stroke="#ba9767" stroke-width=".6"/></pattern></defs><rect width="720" height="480" fill="#edf3e7"/><rect width="720" height="480" fill="url(#grid)"/><path d="M120 58H600M120 52V64M600 52V64M95 80V400M89 80H101M89 400H101" fill="none" stroke="#9aac8c"/><g font-family="system-ui,sans-serif" font-size="11" fill="#6c8060"><text x="345" y="48">60 ft</text><text x="69" y="246" transform="rotate(-90 69 246)">40 ft</text></g><rect x="120" y="80" width="480" height="320" rx="2" fill="#fffdf6" stroke="#7c9670" stroke-width="2"/>']
for x in [120,200,280,360,440,520,600]:
    for y in [80,400]:svg.append(f'<circle cx="{x}" cy="{y}" r="3" fill="#638057"/>')
for cx,cy in [(x,y) for x in [8,22,38,52] for y in [10,30]]:
    px,py=120+cx*8,80+cy*8
    for n in range(8):
        a=n*math.pi/4
        qx,qy=px+29*math.cos(a),py+29*math.sin(a)
        svg.append(f'<rect x="{qx-5:.1f}" y="{qy-4:.1f}" width="10" height="8" rx="2" fill="#e7eddf" stroke="#9fac93" stroke-width=".9" transform="rotate({n*45+90} {qx:.1f} {qy:.1f})"/>')
    svg.append(f'<ellipse cx="{px:.1f}" cy="{py:.1f}" rx="20" ry="20" fill="#faf8ef" stroke="#b5b69c" stroke-width="1.4"/><circle cx="{px:.1f}" cy="{py:.1f}" r="4" fill="#8b9d70"/>')
svg.append('<rect x="312" y="192" width="96" height="96" fill="url(#wood)" stroke="#a17d54" stroke-width="1.3"/><rect x="310" y="226" width="100" height="27" rx="4" fill="#fffdf5e8"/><text x="360" y="244" text-anchor="middle" font-family="system-ui,sans-serif" font-size="10" fill="#7a6244">12′ × 12′ dance floor</text><circle cx="280" cy="240" r="4" fill="#63765a"/><circle cx="440" cy="240" r="4" fill="#63765a"/><text x="360" y="436" text-anchor="middle" font-family="system-ui,sans-serif" font-size="10" fill="#7d8c71">Example arrangement · review clearances with your rental team</text></svg>')
save('assets/example-layout.svg',''.join(svg))
for extra_path in ['/party-rental-inventory-software/','/party-rental-management-software/']:
    if extra_path not in PAGES:
        PAGES.append(extra_path)

